#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m06-kubectl-drills pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m06-kubectl-drills
CHECKS="current-context dns-namespace backend-deployments strategy web-log exec-healthcheck dry-run-manifest diff-output applied-replicas progress-deadline"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m06-kubectl-drills
checks:
  - id: current-context
    describe: context.txt names the context that kubectl uses
    file: kubectl-drills/context.txt
    derive:
      kubectl:
        - config
        - current-context
    expect:
      matches: ^\s*${derived}\s*$
    hint: "`kubectl config current-context` prints the name. Write it to the file with `>`, or list every context with `kubectl config get-contexts`: the current one has a star."
  - id: dns-namespace
    describe: dns-namespace.txt names the namespace of the cluster DNS Deployment
    file: kubectl-drills/dns-namespace.txt
    derive:
      kubectl:
        - get
        - deployments
        - --all-namespaces
        - --selector
        - k8s-app=kube-dns
        - -o
        - json
      jsonpath: "{.items[0].metadata.namespace}"
    expect:
      matches: ^\s*${derived}\s*$
    hint: "`kubectl get deployments --all-namespaces --selector k8s-app=kube-dns --output jsonpath='{.items[0].metadata.namespace}'` prints the name, with no table around it."
  - id: backend-deployments
    describe: backend.txt is the NAME and IMAGE table of the backend Deployments in shelf
    file: kubectl-drills/backend.txt
    derive:
      kubectl:
        - get
        - deployments
        - --namespace
        - shelf
        - --selector
        - app.kubernetes.io/component=backend
        - -o
        - custom-columns=NAME:.metadata.name,IMAGE:.spec.template.spec.containers[0].image
    expect:
      equals: ${derived}
    hint: Use --selector app.kubernetes.io/component=backend and --output custom-columns=NAME:.metadata.name,IMAGE:.spec.template.spec.containers[0].image. Quote the columns in your shell, because the brackets are special.
  - id: strategy
    describe: strategy.txt holds the rollout strategy of shelf-web that describe prints
    file: kubectl-drills/strategy.txt
    derive:
      kubectl:
        - get
        - deployment
        - shelf-web
        - --namespace
        - shelf
        - -o
        - json
      jsonpath: "{.spec.strategy.type}"
    expect:
      matches: (?i)^\s*${derived}\s*$
    hint: Run `kubectl describe deployment shelf-web --namespace shelf` and read the StrategyType line. Write the value into the file.
  - id: web-log
    describe: web-log.txt holds the log of a shelf-web Pod, with the line that reports its port
    file: kubectl-drills/web-log.txt
    derive:
      kubectl:
        - get
        - deployment
        - shelf-web
        - --namespace
        - shelf
        - -o
        - json
      jsonpath: "{.spec.template.spec.containers[0].ports[0].containerPort}"
    expect:
      matches: '"msg":"shelf started".*"port":${derived}\b'
    hint: '`kubectl logs deployment/shelf-web --namespace shelf > kubectl-drills/web-log.txt` writes the log of one Pod, and `--timestamps` is fine too. The line you need has the message "shelf started".'
  - id: exec-healthcheck
    describe: exec.txt holds the word that a successful health check in a shelf-web container prints
    file: kubectl-drills/exec.txt
    expect:
      matches: (?i)^\s*healthy\s*$
    hint: "The image has no shell, so run its own program: `kubectl exec deployment/shelf-web --namespace shelf -- /shelf-web healthcheck && echo healthy > kubectl-drills/exec.txt`. The echo runs only if the check exits 0."
  - id: dry-run-manifest
    describe: shelf-scratch.yaml is the manifest of a Namespace named shelf-scratch
    file: kubectl-drills/shelf-scratch.yaml
    expect:
      jsonpath: "{.kind}/{.metadata.name}"
      equals: Namespace/shelf-scratch
    hint: "`kubectl create namespace shelf-scratch --dry-run=client --output yaml` prints the manifest and creates nothing. Redirect it into the file."
  - id: diff-output
    describe: diff.txt shows replicas changing from 2 to 3, as kubectl diff prints it
    file: kubectl-drills/diff.txt
    expect:
      regexCountAtLeast:
        pattern: "^[-+]\\s+replicas: [23]$"
        count: 2
    hint: Set replicas to 3 in kubectl-drills/shelf-web.yaml, then run `kubectl diff --filename kubectl-drills/shelf-web.yaml > kubectl-drills/diff.txt`. Do this before you apply. kubectl diff exits 1 when it finds differences, and that is normal.
  - id: applied-replicas
    describe: shelf-web was applied from the file with 3 replicas
    kubectl:
      - get
      - deployment
      - shelf-web
      - --namespace
      - shelf
      - -o
      - json
    expect:
      jsonpath: "{.metadata.annotations.kubectl\\.kubernetes\\.io/last-applied-configuration}"
      matches: '"replicas":3[,}]'
    hint: "Apply the edited file: `kubectl apply --filename kubectl-drills/shelf-web.yaml`. `kubectl scale` changes the object but not the stored copy of the manifest."
  - id: progress-deadline
    describe: progress-deadline.txt holds the default that kubectl explain gives for progressDeadlineSeconds
    file: kubectl-drills/progress-deadline.txt
    derive:
      kubectl:
        - get
        - deployment
        - shelf-web
        - --namespace
        - shelf
        - -o
        - json
      jsonpath: "{.spec.progressDeadlineSeconds}"
    expect:
      matches: ^\s*${derived}s?\s*$
    hint: '`kubectl explain deployment.spec.progressDeadlineSeconds` ends with a sentence that starts "Defaults to". Write the number, with or without the s.'
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
